/* ══════════════════════════════════════════════
   APPLICATION STATE
══════════════════════════════════════════════ */
const HERO_IDS = [1, 3, 9, 6]; // Oppenheimer, Dune 2, Dark Knight, Deadpool 3
let curSlide = 0;
let slideTimer = null;
let watchlist = [];
let activeGenre = 'All';

// Watchlist Persistence
try {
  const saved = localStorage.getItem('reelrush_wl');
  if(saved) watchlist = JSON.parse(saved);
} catch(e) {}

function saveWatchlist() {
  try {
    localStorage.setItem('reelrush_wl', JSON.stringify(watchlist));
  } catch(e) {}
  const badge = document.getElementById('wlCount');
  if(badge) badge.textContent = watchlist.length;
}

/* ══════════════════════════════════════════════
   HERO BANNER
══════════════════════════════════════════════ */
function buildHero() {
  const wrap = document.getElementById('heroWrap');
  if (!wrap) return;
  wrap.innerHTML = '';
  
  HERO_IDS.forEach((id, i) => {
    const m = MOVIES.find(x => x.id === id);
    if (!m) return;
    const bgUrl = m.backdrop || m.poster;
    const slide = document.createElement('div');
    slide.className = 'hslide' + (i === 0 ? ' active' : '');
    slide.innerHTML = `
      <div class="hslide-bg" style="background-image: url('${bgUrl}');"></div>
      <div class="hslide-ov"></div>
      <div class="hcontent">
        <div class="hbadge">🔥 Featured Spotlight</div>
        <h1 class="htitle">${m.title}</h1>
        <div class="hmeta">
          <span class="imdb-badge">IMDb</span><span class="rating-val">${m.rating || 'N/A'}</span>
          <div class="dot"></div><span class="hyr">${m.year}</span>
          <div class="dot"></div><span class="hdur">${m.dur}</span>
          <div class="dot"></div><span class="hgenre-tag">${m.genre.join(', ')}</span>
        </div>
        <p class="hdesc">${m.desc}</p>
        <div class="hbtns">
          <button class="btn btn-primary" onclick="openTrailer(${m.id})">▶️ Watch Trailer</button>
          <button class="btn btn-bms" onclick="openBMS(${m.id})">🎟️ Book Tickets</button>
          <button class="btn btn-trailer" onclick="openDet(${m.id})">ℹ️ Details</button>
          <button class="btn btn-ghost" onclick="toggleWL(${m.id})">${watchlist.some(x=>x.id===m.id)?'✓ In List':'＋ My List'}</button>
        </div>
      </div>
    `;
    wrap.appendChild(slide);
  });

  // Dots
  const dotsD = document.createElement('div');
  dotsD.className = 'sdots';
  HERO_IDS.forEach((_, i) => {
    const d = document.createElement('div');
    d.className = 'sdot' + (i === 0 ? ' active' : '');
    d.onclick = () => goSlide(i);
    dotsD.appendChild(d);
  });
  wrap.appendChild(dotsD);

  // Arrow controls
  ['prev', 'next'].forEach(dir => {
    const b = document.createElement('button');
    b.className = 'sarrow ' + dir;
    b.innerHTML = dir === 'prev' 
      ? '<svg width="20" height="20" fill="none" viewBox="0 0 24 24"><path d="M15 18l-6-6 6-6" stroke="#fff" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg>'
      : '<svg width="20" height="20" fill="none" viewBox="0 0 24 24"><path d="M9 18l6-6-6-6" stroke="#fff" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg>';
    b.onclick = () => goSlide(dir === 'prev' ? (curSlide - 1 + HERO_IDS.length) % HERO_IDS.length : (curSlide + 1) % HERO_IDS.length);
    wrap.appendChild(b);
  });

  startSlide();
}

function goSlide(idx) {
  const slides = document.querySelectorAll('.hslide');
  const dots = document.querySelectorAll('.sdot');
  if(!slides.length) return;
  slides[curSlide].classList.remove('active');
  dots[curSlide].classList.remove('active');
  curSlide = idx;
  slides[curSlide].classList.add('active');
  dots[curSlide].classList.add('active');
  clearInterval(slideTimer);
  startSlide();
}

function startSlide() {
  slideTimer = setInterval(() => goSlide((curSlide + 1) % HERO_IDS.length), 6000);
}

/* ══════════════════════════════════════════════
   CARD GENERATORS
══════════════════════════════════════════════ */
function mCard(m, badgeCls, badgeText) {
  const div = document.createElement('div');
  div.className = 'mcard';
  div.onclick = () => openDet(m.id);
  const inWL = watchlist.some(x => x.id === m.id);
  const posterSrc = m.poster || 'https://via.placeholder.com/300x450/11111a/ffffff?text='+encodeURIComponent(m.title);

  div.innerHTML = `
    ${badgeCls ? `<div class="cbadge ${badgeCls}">${badgeText}</div>` : ''}
    <div class="cposter-box">
      <img class="cposter-img" src="${posterSrc}" alt="${m.title}" loading="lazy" onerror="this.src='https://via.placeholder.com/300x450/11111a/ffffff?text=Poster'"/>
      <div class="cov">
        <div class="cov-btns">
          <button class="cov-btn t-btn" onclick="event.stopPropagation();openTrailer(${m.id})">▶️ Trailer</button>
          <button class="cov-btn b-btn" onclick="event.stopPropagation();openBMS(${m.id})">🎟️ Book Tickets</button>
          <button class="cov-btn w-btn" onclick="event.stopPropagation();toggleWL(${m.id})">${inWL ? '✓ In List' : '＋ Add List'}</button>
        </div>
      </div>
    </div>
    <div class="cinfo">
      <div class="ctitle" title="${m.title}">${m.title}</div>
      <div class="cmeta">
        <span class="cyr">${m.year}</span>
        ${m.rating ? `<div class="cimdb">⭐ <span>${m.rating}</span></div>` : '<span style="color:#a855f7;font-size:11px;font-weight:700">Soon</span>'}
      </div>
      <div class="cgenre-txt">${m.genre.join(', ')}</div>
    </div>
  `;
  return div;
}

function tCard(m) {
  const div = document.createElement('div');
  div.className = 'tcard';
  div.onclick = () => openDet(m.id);
  const bgImg = m.backdrop || m.poster;
  div.innerHTML = `
    <div class="tcard-bg" style="background-image: url('${bgImg}');"></div>
    <div class="tcard-ov">
      <div class="tcard-rank">#${m.rank}</div>
      <div class="tcard-title">${m.title}</div>
      <div class="tcard-sub">${m.year} · ${m.genre.slice(0, 2).join(', ')}</div>
      <div class="tcard-imdb">⭐ IMDb ${m.rating}</div>
    </div>
  `;
  return div;
}

function uCard(m) {
  const div = document.createElement('div');
  div.className = 'ucard';
  div.onclick = () => openDet(m.id);
  const posterSrc = m.poster || 'https://via.placeholder.com/300x450/11111a/ffffff?text='+encodeURIComponent(m.title);
  div.innerHTML = `
    <div class="cbadge badge-web">🗓️ Upcoming</div>
    <div class="rdate-tag">${m.releaseDate || 'Coming Soon'}</div>
    <div class="upost-box">
      <img class="upost-img" src="${posterSrc}" alt="${m.title}" loading="lazy"/>
    </div>
    <div class="cinfo">
      <div class="ctitle" title="${m.title}">${m.title}</div>
      <div class="cmeta">
        <span class="cyr">${m.year}</span>
        <span style="color:#a855f7;font-size:11px;font-weight:700">${m.releaseDate || '2024'}</span>
      </div>
      <div class="cgenre-txt">${m.genre.join(', ')}</div>
    </div>
  `;
  return div;
}

function newsCard(n) {
  const div = document.createElement('div');
  div.className = 'news-card';
  div.innerHTML = `
    <div class="news-thumb" style="background:linear-gradient(135deg,${n.color} 0%,#0e0e18 100%)">
      <span style="font-size:52px">${n.emoji}</span>
      <div class="news-cat">${n.category}</div>
    </div>
    <div class="news-body">
      <div class="news-date">${n.date} · By ${n.author}</div>
      <div class="news-title">${n.title}</div>
      <div class="news-excerpt">${n.excerpt}</div>
      <div class="news-footer">
        <span style="color:#71717a">ReelRush Cinema Journal</span>
        <span class="news-read">Read Article →</span>
      </div>
    </div>
  `;
  return div;
}

function fillRow(id, items, creator, ...args) {
  const r = document.getElementById(id);
  if (!r) return;
  r.innerHTML = '';
  if (!items.length) {
    r.innerHTML = '<div style="color:#71717a;font-size:13px;padding:16px">No titles available in this category for the active filter.</div>';
    return;
  }
  items.forEach(m => r.appendChild(creator(m, ...args)));
}

